import { sprintf }				from 'sprintf-js';
import { AccCatId, type AccConfig, type SrvCharacteristic, type GeneratorContext, type GeneratorResult } from '../lib/types';
import { constChar, objName, onlyAck, sortBy } from '../lib/helpers';


// ~~~~~~~~
// ROLE_MAP
// ~~~~~~~~
// accessory generated by createByRole() for a state role
const ROLE_MAP: Record<string, { category: string, type: string, characteristics: (id: string, name: string) => SrvCharacteristic[] }> = {
	'sensor.contact': {
		category: AccCatId.Sensor,
		type: 'ContactSensor',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('ContactSensorState', id),
		],
	},
	'sensor.motion': {
		category: AccCatId.Sensor,
		type: 'MotionSensor',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('MotionDetected', id),
		],
	},
	'sensor.occupancy': {
		category: AccCatId.Sensor,
		type: 'OccupancySensor',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('OccupancyDetected', id),
		],
	},
	'sensor.leak': {
		category: AccCatId.Sensor,
		type: 'LeakSensor',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('LeakDetected', id),
		],
	},
	'switch': {
		category: AccCatId.Switch,
		type: 'Switch',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('On', id),
		],
	},
	'switch.light': {
		category: AccCatId.Lightbulb,
		type: 'Lightbulb',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('On', id),
		],
	},
	'switch.fan': {
		category: AccCatId.Fan,
		type: 'Fan',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('On', id),
		],
	},
	'switch.lock.door': {
		category: AccCatId.Door_lock,
		type: 'LockMechanism',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('LockTargetState', id, { 'conversionFunction': 'invert' }),
			onlyAck('LockCurrentState', id + '_status', { 'conversionFunction': 'invert' }),
		],
	},
	'switch.garage': {
		category: AccCatId.Garage_door_opener,
		type: 'GarageDoorOpener',
		characteristics: (id, name) => [
			constChar('Name', name),
			onlyAck('TargetDoorState', id, { 'conversionFunction': 'invert' }),
			onlyAck('CurrentDoorState', id + '_status', { 'conversionFunction': 'invert' }),
			constChar('ObstructionDetected', false),
		],
	},
};


// createByRole: one accessory per state whose role is listed in ROLE_MAP (used for rpi-io and switchboard-io);
// states with any other role are ignored
export async function createByRole({ adapter, srcInstId }: GeneratorContext): Promise<GeneratorResult> {
	const accConfigs: AccConfig[] = [];
	const historyIds: string[] = [];

	const stateObjs = await adapter.getForeignObjectsAsync(`${srcInstId}.*`, 'state');
	for (const stateObj of Object.values(stateObjs).sort(sortBy('_id'))) {
		const objId		= stateObj._id;									//   '0_userdata.0.pin.tür_tag'
		const idPath	= stateObj._id.split('.');						// [ '0_userdata', '0', 'pin', 'tür_tag' ]
		const objRole	= stateObj.common.role;							// 'value.temperature'
		const name		= objName(stateObj);								// 'Haustür'

		// yahka device config
		const accConfig: AccConfig = {
			'category':			'',
			'name':				objId,									// NOTE: yahka adapter uses 'name' to build homekit UUID!
			'manufacturer':		idPath.slice(0,2).join('.'),			// visible within iOS home app
			'serial':			idPath.slice(2  ).join('.'),			// visible within iOS home app
			'model':			name,									// visible within iOS home app
			'services':			[],										// default
			'groupString':		idPath.slice(0,2).join('.')				// used by adapter only
		};

		// services by role
		const mapped = Object.hasOwn(ROLE_MAP, objRole) ? ROLE_MAP[objRole] : undefined;
		if (mapped) {
			accConfig.category = mapped.category;
			accConfig.services = [
				{
					'type': mapped.type,
					'subType': '',
					'name': name,
					'characteristics': mapped.characteristics(objId, name),
				}
			];
		}

		// add accConfig
		if (accConfig.services.length > 0) {
			accConfigs.push(accConfig);
			for (const accService of accConfig.services) {
				adapter.log.debug(sprintf('%-31s %-20s %-50s %s', 'createByRole()', accService.type, accConfig.name, accService.name));
			}
		}
	}

	return { devices: accConfigs, invalid: [], historyIds };
}
